def book_brute(calendar_counts, start, end):
    for t in range(start, end):                       # check every individual time unit
        if calendar_counts.get(t, 0) + 1 > 2:
            return False
    for t in range(start, end):
        calendar_counts[t] = calendar_counts.get(t, 0) + 1
    return True

