import java.util.*;

class MyCalendarTwo {
    List<int[]> bookings = new ArrayList<>();
    List<int[]> overlaps = new ArrayList<>();

    boolean book(int start, int end) {
        for (int[] o : overlaps) {
            if (start < o[1] && o[0] < end) return false;               // would create a triple booking
        }
        for (int[] b : bookings) {
            if (start < b[1] && b[0] < end) {
                overlaps.add(new int[]{Math.max(start, b[0]), Math.min(end, b[1])});  // new double region
            }
        }
        bookings.add(new int[]{start, end});
        return true;
    }
}

