using namespace std;

class MyCalendarTwo {
public:
    vector<pair<int,int>> bookings, overlaps;

    bool book(int start, int end) {
        for (auto& [s, e] : overlaps) {
            if (start < e && s < end) return false;                       // would create a triple booking
        }
        for (auto& [s, e] : bookings) {
            if (start < e && s < end) {
                overlaps.push_back({max(start, s), min(end, e)});           // new double region
            }
        }
        bookings.push_back({start, end});
        return true;
    }
};
